// Device-only exchange checklist. Never stored in campaign data or exported to the DM.
export const newExchange=state=>({revision:state.current_revision,copied_state:false,copied_instructions:false,update_id:null,receipt_pasted:false,handoff_visited:false,handoff_copied:false,handoff_checked:false});
export function restoreExchange(saved,state){const fresh=newExchange(state);if(!saved||saved.revision!==state.current_revision)return fresh;for(const key of Object.keys(fresh))if(typeof fresh[key]==='boolean')fresh[key]=saved[key]===true;if(typeof saved.update_id==='string'&&state.transactions.some(t=>t.update?.update_id===saved.update_id))fresh.update_id=saved.update_id;if(!fresh.update_id){fresh.receipt_pasted=false;fresh.handoff_checked=false;}return fresh;}
export function importConfirmed(previous,state,receipt){return {...newExchange(state),copied_state:previous.copied_state,copied_instructions:previous.copied_instructions,update_id:receipt.update_id};}
export function exchangeStatus(w,attention){const done=[w.copied_state&&w.copied_instructions,!!w.update_id,!!w.update_id&&w.receipt_pasted,!!w.update_id&&w.receipt_pasted&&w.handoff_checked&&w.handoff_visited&&(!attention||w.handoff_copied)];return {done,allDone:done.every(Boolean),canFinish:done[2]&&w.handoff_visited&&(!attention||w.handoff_copied)};}
